1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	  enchantment?: number;
9	}
10	
11	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	};
17	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
18	const COMPONENT_BASE_PREMIUM = 25;
19	const BLOCK_SIZE = 3;
20	const BLOCK_BASE_PREMIUM = 60;
21	const CURSE_SURCHARGE_RATE = 0.5;
22	const HIGH_ENCHANTMENT_LEVEL = 5;
23	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
24	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
25	const PROCESSING_FEE = 5;
26	
27	function isComponent(item: Item): boolean {
28	  return COMPONENT_TYPES.has(item.type);
29	}
30	
31	function isMainItem(item: Item): boolean {
32	  return !isComponent(item);
33	}
34	
35	function mainItemBasePremium(item: Item): number {
36	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
37	}
38	
39	function alikeGroupBasePremium(count: number): number {
40	  return count === BLOCK_SIZE
41	    ? BLOCK_BASE_PREMIUM
42	    : count * COMPONENT_BASE_PREMIUM;
43	}
44	
45	/** Components are "alike" when they are of exactly the same type. */
46	function alikeKey(component: Item): string {
47	  return component.type;
48	}
49	
50	function componentsBasePremium(components: Item[]): number {
51	  const countsPerAlikeGroup = new Map<string, number>();
52	  for (const component of components) {
53	    const key = alikeKey(component);
54	    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
55	  }
56	  return [...countsPerAlikeGroup.values()].reduce(
57	    (total, count) => total + alikeGroupBasePremium(count),
58	    0,
59	  );
60	}
61	
62	function curseSurcharge(item: Item): number {
63	  return item.cursed === true
64	    ? mainItemBasePremium(item) * CURSE_SURCHARGE_RATE
65	    : 0;
66	}
67	
68	/**
69	 * Item-specific modifiers apply to the base premium of the affected item and
70	 * are added to it, never multiplied onto it.
71	 */
72	function isHighlyEnchanted(item: Item): boolean {
73	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
74	}
75	
76	function highEnchantmentSurcharge(item: Item): number {
77	  return isHighlyEnchanted(item)
78	    ? mainItemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
79	    : 0;
80	}
81	
82	function itemSpecificModifiers(item: Item): number {
83	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
84	}
85	
86	function mainItemsBasePremium(mainItems: Item[]): number {
87	  return mainItems.reduce((total, item) => total + mainItemBasePremium(item), 0);
88	}
89	
90	/** The policy base premium: the sum of all unmodified item base premiums. */
91	function policyBasePremiumFor(items: Item[]): number {
92	  return (
93	    mainItemsBasePremium(items.filter(isMainItem)) +
94	    componentsBasePremium(items.filter(isComponent))
95	  );
96	}
97	
98	/** The item-specific surcharges of every affected item, summed. */
99	function itemSpecificModifiersFor(items: Item[]): number {
100	  return items
101	    .filter(isMainItem)
102	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
103	}
104	
105	function roundInMHPCOsFavour(premium: number): number {
106	  return Math.ceil(premium);
107	}
108	
109	/**
110	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
111	 * base premiums) and are added to it, never multiplied onto it.
112	 */
113	function policyWideModifiers(policyBasePremium: number): number {
114	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
115	}
116	
117	export function quote(customer: Customer, items: Item[]): number {
118	  const policyBasePremium = policyBasePremiumFor(items);
119	  const premium =
120	    policyBasePremium +
121	    itemSpecificModifiersFor(items) +
122	    policyWideModifiers(policyBasePremium) +
123	    PROCESSING_FEE;
124	  return roundInMHPCOsFavour(premium);
125	}
